-- The blog, «مجله‌ی کیوا» (completion roadmap, phase 15, section 20.4).
--
-- Categories and authors have no endpoint of the panel (decision 1): they are made here and changed with SQL, like
-- sitecontent. A post is a plain table, not event-sourced: its history is the change log's. Its blocks are JSONB, each
-- kind with only its own fields (BlogBlocks, decision 7). Seen by the shop = PUBLISHED with publishedAt reached
-- (decision 3): no job publishes a scheduled post, the reading does.

CREATE TABLE blogcategory_tbl
(
    "pId"       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug        VARCHAR(60) NOT NULL UNIQUE CHECK (slug ~ '^(?=.*[a-z])[a-z0-9]+(-[a-z0-9]+)*$'),
    name        VARCHAR(60) NOT NULL CHECK (btrim(name) <> ''),
    "sortOrder" INTEGER     NOT NULL DEFAULT 0
);

CREATE TABLE blogauthor_tbl
(
    "pId"           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name            VARCHAR(60) NOT NULL CHECK (btrim(name) <> ''),
    title           VARCHAR(80),
    bio             VARCHAR(500),
    "avatarMediaId" VARCHAR(26) CHECK ("avatarMediaId" ~ '^med_[0-9A-Za-z]{22}$'),
    "isDefault"     BOOLEAN     NOT NULL DEFAULT FALSE
);
-- At most one default author: the one a post without authorId gets.
CREATE UNIQUE INDEX blogauthor_one_default_idx ON blogauthor_tbl ("isDefault") WHERE "isDefault";

-- The prototype's categories (kiva-fe's blog-data.js), and the default author.
